-- ZoneClan Database Anonymization Script
-- Run this after generating discord_id_mapping.csv with the C# tool
--
-- WARNING: This script anonymizes all Discord IDs and player names in the database.
-- Make sure you have a backup before running this!

SET @start_time = NOW();
SELECT CONCAT('Starting anonymization at ', @start_time) AS 'Status';

-- Create temporary mapping table
CREATE TEMPORARY TABLE discord_id_mapping (
    old_id BIGINT PRIMARY KEY,
    new_id BIGINT NOT NULL UNIQUE,
    new_nickname VARCHAR(64) NOT NULL
);

-- Load mapping from CSV generated by the C# tool
-- Note: You need to generate discord_id_mapping.csv first
LOAD DATA LOCAL INFILE 'discord_id_mapping.csv'
INTO TABLE discord_id_mapping
FIELDS TERMINATED BY ','
LINES TERMINATED BY '\n'
IGNORE 1 LINES; -- Skip header row

SELECT CONCAT('Loaded ', COUNT(*), ' mappings') AS 'Status' FROM discord_id_mapping;

-- Disable foreign key checks
SET FOREIGN_KEY_CHECKS = 0;

-- Update players table (main table)
UPDATE players p
JOIN discord_id_mapping m ON p.discord_id = m.old_id
SET p.discord_id = m.new_id, p.ingame_name = m.new_nickname;

SELECT CONCAT('Updated players: ', ROW_COUNT()) AS 'Status';

-- Update match_tab_players table
UPDATE match_tab_players mtp
JOIN discord_id_mapping m ON mtp.player_id = m.old_id
SET mtp.player_id = m.new_id, mtp.nickname = m.new_nickname;

SELECT CONCAT('Updated match_tab_players: ', ROW_COUNT()) AS 'Status';

-- Update player_stage_status table
UPDATE player_stage_status pss
JOIN discord_id_mapping m ON pss.player_id = m.old_id
SET pss.player_id = m.new_id;

SELECT CONCAT('Updated player_stage_status: ', ROW_COUNT()) AS 'Status';

-- Update player_builds table
UPDATE player_builds pb
JOIN discord_id_mapping m ON pb.player_id = m.old_id
SET pb.player_id = m.new_id;

SELECT CONCAT('Updated player_builds: ', ROW_COUNT()) AS 'Status';

-- Update player_armor_stats table
UPDATE player_armor_stats pas
JOIN discord_id_mapping m ON pas.player_id = m.old_id
SET pas.player_id = m.new_id;

SELECT CONCAT('Updated player_armor_stats: ', ROW_COUNT()) AS 'Status';

-- Update player_roles table
UPDATE player_roles pr
JOIN discord_id_mapping m ON pr.player_id = m.old_id
SET pr.player_id = m.new_id;

SELECT CONCAT('Updated player_roles: ', ROW_COUNT()) AS 'Status';

-- Update player_penalties table
UPDATE player_penalties pp
JOIN discord_id_mapping m ON pp.player_id = m.old_id
SET pp.player_id = m.new_id;

SELECT CONCAT('Updated player_penalties: ', ROW_COUNT()) AS 'Status';

-- Update player_snipers table
UPDATE player_snipers ps
JOIN discord_id_mapping m ON ps.player_id = m.old_id
SET ps.player_id = m.new_id;

SELECT CONCAT('Updated player_snipers: ', ROW_COUNT()) AS 'Status';

-- Update player_notes table
UPDATE player_notes pn
JOIN discord_id_mapping m ON pn.player_id = m.old_id
SET pn.player_id = m.new_id;

SELECT CONCAT('Updated player_notes: ', ROW_COUNT()) AS 'Status';

-- Update squad_members table
UPDATE squad_members sm
JOIN discord_id_mapping m ON sm.player_id = m.old_id
SET sm.player_id = m.new_id;

SELECT CONCAT('Updated squad_members: ', ROW_COUNT()) AS 'Status';

-- Update attendance table
UPDATE attendance a
JOIN discord_id_mapping m ON a.player_id = m.old_id
SET a.player_id = m.new_id;

SELECT CONCAT('Updated attendance: ', ROW_COUNT()) AS 'Status';

-- Update player_bans table
UPDATE player_bans pb
JOIN discord_id_mapping m ON pb.player_id = m.old_id
SET pb.player_id = m.new_id;

SELECT CONCAT('Updated player_bans: ', ROW_COUNT()) AS 'Status';

-- Anonymize guild_id in clan_settings
UPDATE clan_settings
SET guild_id = 1000000000000000000,
    updated_by = 0;

SELECT CONCAT('Anonymized clan_settings') AS 'Status';

-- Re-enable foreign key checks
SET FOREIGN_KEY_CHECKS = 1;

-- Drop temporary table
DROP TEMPORARY TABLE discord_id_mapping;

-- Verification query
SELECT
    COUNT(*) as total_players,
    COUNT(DISTINCT discord_id) as unique_discord_ids,
    MIN(discord_id) as min_discord_id,
    MAX(discord_id) as max_discord_id
FROM players;

-- Check if all Discord IDs are in the anonymized range (11xxxxxxxxxxxxxxxxxx)
SELECT
    COUNT(*) as players_with_real_discord_ids
FROM players
WHERE discord_id < 1100000000000000000 OR discord_id > 1199999999999999999;

SET @end_time = NOW();
SELECT CONCAT('Anonymization completed at ', @end_time) AS 'Status';
SELECT TIMEDIFF(@end_time, @start_time) AS 'Total Duration';

-- Final summary
SELECT '✅ Database anonymization completed successfully!' AS 'Result';
SELECT '   - All Discord IDs replaced with anonymized values' AS 'Result';
SELECT '   - Player names replaced with gaming-style nicknames' AS 'Result';
SELECT '   - Guild ID anonymized in clan_settings' AS 'Result';
SELECT '   - Foreign key relationships preserved' AS 'Result';